using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class ModConfigurations {
  const int MaxStore=1048576,MaxProfiles=200;
  static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
  sealed class Profile {public string id,name,updated;public string[] mods;}
  sealed class Store {public int version;public List<Profile> profiles;}
  sealed class Snapshot {public string File,Stamp;public byte[] Bytes,Default;public Store Store;}
  internal sealed class SortResult {public string[] mods,warnings,errors,violations;public string[][] cycles=new string[0][];public string[] blockedByCycles=new string[0];public bool changed;}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=2097152,RecursionLimit=20};}
  static string Hash(byte[] bytes){return DlssInstaller.Hash(bytes).ToLowerInvariant();}
  static void Safe(string path){LauncherMaintenance.NoReparse(path);}
  static string StoreFile(Engine e){string root=Path.GetFullPath(Path.Combine(e.Data,"mod-profiles")),file=Path.GetFullPath(Path.Combine(root,LaunchProfiles.Key(e)+".json"));if(!file.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("模组配置路径越界。");Safe(file);return file;}
  static bool Opaque(string id){return id!=null&&Regex.IsMatch(id,"^[a-f0-9]{32}$");}
  static string Name(string name){name=(name??"").Trim();if(name.Length==0||name.Length>100||name.Any(char.IsControl))throw new Exception("配置名称需为 1 至 100 个可显示字符。");return name;}
  static string[] Mods(string[] mods){if(mods==null||mods.Length>2000)throw new Exception("无效模组清单或超出数量限制。");var result=mods.Select(s=>s==null?null:s.Trim()).ToArray();if(result.Any(s=>!SaveProfiles.Id(s))||result.Distinct(StringComparer.Ordinal).Count()!=result.Length)throw new Exception("无效或重复的模组 ID。");return result;}
  internal static string[] ValidatePreflightMods(string[] mods){var result=Mods(mods);if(result.Any(id=>id.Split(new[]{'/','\\'}).Any(part=>part=="."||part=="..")))throw new Exception("模组 ID 不能含路径遍历片段。");return result;}
  static Snapshot Load(Engine e){string file=StoreFile(e);byte[] bytes=null;var store=new Store{version=1,profiles=new List<Profile>()};if(File.Exists(file)){if(new FileInfo(file).Length>MaxStore)throw new Exception("模组配置集合超出大小限制。");bytes=File.ReadAllBytes(file);if(bytes.Length>MaxStore)throw new Exception("模组配置集合超出大小限制。");try{store=Json().Deserialize<Store>(Utf8.GetString(bytes));if(store==null||store.version!=1||store.profiles==null||store.profiles.Count>MaxProfiles)throw new Exception();var identities=new HashSet<string>(StringComparer.Ordinal);foreach(var profile in store.profiles){DateTime updated;if(profile==null||!Opaque(profile.id)||!identities.Add(profile.id)||Name(profile.name)!=profile.name||!DateTime.TryParse(profile.updated,out updated)||!Mods(profile.mods).SequenceEqual(profile.mods))throw new Exception();}}catch{throw new Exception("模组配置集合损坏或格式无效；未重置，请核对原文件。");}}
   byte[] defaults=SaveProfiles.DefaultBytes(e);string stamp="profiles:"+Hash(Utf8.GetBytes((bytes==null?"absent":Hash(bytes))+"|"+(defaults==null?"absent":Hash(defaults))));return new Snapshot{File=file,Bytes=bytes,Default=defaults,Store=store,Stamp=stamp};}
  static Profile Find(Snapshot snapshot,string id){if(!Opaque(id))throw new Exception("无效模组配置标识。");var profile=snapshot.Store.profiles.FirstOrDefault(p=>p.id==id);if(profile==null)throw new Exception("模组配置不存在，请刷新。");return profile;}
  static object Dto(Profile p,string stamp){return new{id=p.id,name=p.name,stamp=stamp,mods=Ordinary(p.mods)};}
  static void CheckStamp(Snapshot s,string stamp){if(string.IsNullOrEmpty(stamp)||stamp!=s.Stamp)throw new Exception("模组配置或默认清单已被其他程序修改，请刷新。");}
  static void StorageGuard(Engine e){Safe(e.Data);Safe(StoreFile(e));}
  static void Guard(Engine e){foreach(string path in new[]{e.Game,e.Config,e.User,e.Mods,e.Data})Safe(path);e.GuardContent();}
  static T Locked<T>(Engine e,Func<T> work,Action guard=null){string name="Local\\OrangeLaunch-"+DlssInstaller.Hash(Utf8.GetBytes(Path.GetFullPath(e.User).ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new Exception("另一个启动或配置任务正在运行，请稍后重试。");if(guard==null)StorageGuard(e);else guard();return work();}finally{if(held)mutex.ReleaseMutex();}}}
  public static object List(Engine e){return Locked<object>(e,()=>{var s=Load(e);return new{stamp=s.Stamp,profiles=s.Store.profiles.Select(p=>new{id=p.id,name=p.name,modCount=Ordinary(p.mods).Length,updated=p.updated}).ToArray(),activeMods=Ordinary(LaunchProfiles.PersistentMods(e,SaveProfiles.DefaultMods(s.Default)))};});}
  public static object Read(Engine e,string id){var s=Load(e);return Dto(Find(s,id),s.Stamp);}
  static string Field(Dictionary<string,object> payload,string key,bool optional=false){object raw;if(payload==null||!payload.TryGetValue(key,out raw)||raw==null){if(optional)return null;throw new Exception("配置参数缺少 "+key+"。");}if(!(raw is string))throw new Exception("配置参数 "+key+" 必须为文本。");return (string)raw;}
  static string[] PayloadMods(Dictionary<string,object> payload){object value;if(payload==null||!payload.TryGetValue("mods",out value)||value is string||!(value is IEnumerable))throw new Exception("mods 必须为模组 ID 数组。");var items=((IEnumerable)value).Cast<object>().ToArray();if(items.Any(item=>!(item is string)))throw new Exception("mods 仅支持文本 ID。");return Mods(items.Cast<string>().ToArray());}
  public static object Save(Engine e,Dictionary<string,object> payload){string id=Field(payload,"id",true),name=Name(Field(payload,"name")),stamp=Field(payload,"stamp");string[] mods=PayloadMods(payload);return Locked<object>(e,()=>{var s=Load(e);CheckStamp(s,stamp);Profile profile;if(string.IsNullOrEmpty(id)){if(s.Store.profiles.Count>=MaxProfiles)throw new Exception("模组配置数量已达上限。");profile=new Profile{id=Guid.NewGuid().ToString("N")};s.Store.profiles.Add(profile);}else profile=Find(s,id);profile.name=name;profile.mods=Ordinary(LaunchProfiles.PersistentMods(e,mods));profile.updated=DateTime.UtcNow.ToString("o");Persist(e,s,stamp);return Read(e,profile.id);});}
  public static object Delete(Engine e,string id,string stamp){return Locked<object>(e,()=>{var s=Load(e);CheckStamp(s,stamp);s.Store.profiles.Remove(Find(s,id));Persist(e,s,stamp);return new{message="已删除本地模组配置；存档与默认清单未修改。"};});}
  static void Persist(Engine e,Snapshot snapshot,string stamp){byte[] output=Utf8.GetBytes(Json().Serialize(snapshot.Store));if(output.Length>MaxStore)throw new Exception("模组配置集合超出大小限制。");Atomic(snapshot.File,output,()=>{StorageGuard(e);CheckStamp(Load(e),stamp);});}
  static void Atomic(string file,byte[] output,Action beforeReplace){Safe(file);string dir=Path.GetDirectoryName(file);Safe(dir);Directory.CreateDirectory(dir);string temporary=file+".orange-"+Guid.NewGuid().ToString("N")+".tmp";try{Safe(temporary);using(var stream=new FileStream(temporary,FileMode.CreateNew,FileAccess.Write,FileShare.None)){stream.Write(output,0,output.Length);stream.Flush(true);}beforeReplace();Safe(file);if(File.Exists(file))File.Replace(temporary,file,null);else File.Move(temporary,file);}finally{Safe(temporary);if(File.Exists(temporary))File.Delete(temporary);}}
  internal static string[] Managed(string[] active){var managed=new HashSet<string>(Engine.ModIds.Concat(new[]{ShootClient.Id,ChinesePatch.Id,PresentationBridge.Id}).Concat(ViewpointAddons.All.Select(a=>a.Id)),StringComparer.Ordinal);return active.Where(id=>id!=null&&managed.Contains(id.TrimStart('\\'))).ToArray();}
  internal static string[] Ordinary(IEnumerable<string> ids){var values=ids.ToArray();var managed=new HashSet<string>(Managed(values),StringComparer.Ordinal);return values.Where(id=>!managed.Contains(id)).ToArray();}
  internal static string[] Merge(Engine e,IEnumerable<string> ids,string[] active){if(e.OwnedLaunch){var managed=e.OwnedComponents().ManagedIds();return ids.Where(id=>!managed.Contains(id.TrimStart('\\'))).Distinct(StringComparer.Ordinal).ToArray();}return LaunchProfiles.PersistentMods(e,Managed(active).Concat(Ordinary(ids))).Distinct(StringComparer.Ordinal).ToArray();}
  static HashSet<string> LoaderIds(Engine e,string[] active){var result=new HashSet<string>(StringComparer.Ordinal);if(active==null||!active.Any(id=>id.TrimStart('\\')=="ZombieBuddy"))return result;try{Safe(e.Config);string jar=Path.Combine(e.Game,"ZombieBuddy.jar"),native=Path.Combine(e.Game,"zbNative.dll");Safe(jar);Safe(native);if(CoreComponents.FrameworkReady(e)&&File.Exists(jar)&&File.Exists(native))result.UnionWith(active.Where(id=>id.TrimStart('\\')=="ZombieBuddy"));}catch{}return result;}
  public static object Activate(Engine e,string id,string stamp,bool confirmed){if(!confirmed)throw new Exception("启用模组配置需要明确确认默认清单变化。");return Locked<object>(e,()=>{var s=Load(e);CheckStamp(s,stamp);var profile=Find(s,id);if(e.OwnedLaunch){e.OwnedComponents().SaveOrdinary(profile.mods,CancellationToken.None);return new{message="已保存此配置的普通模组清单，下次启动生效。"};}string[] active=SaveProfiles.DefaultMods(s.Default),retained=Managed(active);string[] combined=Mods(Merge(e,profile.mods,active));var warnings=new List<string>();var entries=SaveProfiles.Entries(e,warnings);var result=Order(combined,entries,warnings,LoaderIds(e,retained));if(result.errors.Length>0)throw new Exception(string.Join("\n",result.errors));combined=result.mods;byte[] output=SaveProfiles.ReplaceDefaultMods(s.Default,combined);string backup=Path.Combine(e.Data,"backups","mod-profile-"+Guid.NewGuid().ToString("N"));Safe(backup);Guard(e);CheckStamp(Load(e),stamp);Directory.CreateDirectory(backup);if(s.Default!=null)File.WriteAllBytes(Path.Combine(backup,"default.txt"),s.Default);File.WriteAllText(Path.Combine(backup,"restore.txt"),"核对备份后可恢复默认模组文件：\r\n"+e.Mods+"\r\n原文件"+(s.Default==null?"不存在；恢复时仅移走此次创建的文件。":"已保存为 default.txt；整份恢复会覆盖后续修改。"),Utf8);Atomic(e.Mods,output,()=>{Guard(e);CheckStamp(Load(e),stamp);});e.LastBackup=backup;string[] removed=active.Except(combined,StringComparer.Ordinal).ToArray();return new{message="已启用本地模组配置，下次启动生效。"+(retained.Length>0?" 已保留现有 Viewpoint 客户端组件。":"")+(removed.Length>0?" 已移除普通模组："+string.Join("、",removed.Take(40))+(removed.Length>40?"…":"")+"。":"")+" 原清单备份："+backup};},()=>Guard(e));}
  public static object AutoSortDefault(Engine e,bool confirmed){
   if(!confirmed)throw new Exception("自动排序需要明确确认默认清单变化。");
   return Locked<object>(e,()=>{byte[] original=SaveProfiles.DefaultBytes(e);string[] mods=ValidatePreflightMods(SaveProfiles.DefaultMods(original));SaveProfiles.ReplaceDefaultMods(original,mods);var result=SortForPreflight(e,mods);if(result.errors.Length>0)throw new Exception(string.Join("\n",result.errors));if(!result.changed)return new{message="默认模组顺序已符合已知依赖，无需修改。",changed=false,mods=result.mods};byte[] output=SaveProfiles.ReplaceDefaultMods(original,result.mods);Atomic(e.Mods,output,()=>{byte[] current=SaveProfiles.DefaultBytes(e);if(original==null?current!=null:current==null||!original.SequenceEqual(current))throw new Exception("默认模组清单已被其他程序修改，请刷新后重新排序。");});return new{message="已按已知依赖自动排序默认模组；启用的模组未增减。",changed=true,mods=result.mods};},()=>{Safe(e.User);Safe(e.Mods);});
  }
  public static object Sort(Engine e,string[] mods){var warnings=new List<string>();try{var active=SaveProfiles.DefaultMods(SaveProfiles.DefaultBytes(e));var ordinary=Ordinary(ValidatePreflightMods(mods));var result=Order(Merge(e,ordinary,active),SaveProfiles.Entries(e,warnings),warnings,LoaderIds(e,active));result.mods=result.errors.Length==0?Ordinary(result.mods):mods;result.changed=result.errors.Length==0&&!result.mods.SequenceEqual(Ordinary(mods));return result;}catch(Exception ex){return new SortResult{mods=mods??new string[0],errors=new[]{ex.Message},warnings=Bound(warnings),violations=new string[0]};}}
  internal static SortResult SortForSave(Engine e,string[] mods){var warnings=new List<string>();return Order(mods,SaveProfiles.Entries(e,warnings),warnings,LoaderIds(e,mods));}
  internal static SortResult SortForPlayProfile(Engine e,string[] mods,out string evidence){var budget=new LaunchReadBudget(16777216);var warnings=new List<string>();var entries=SaveProfiles.Entries(e,warnings,true,budget);var allowed=LoaderIds(e,mods);evidence=Json().Serialize(entries.Select(x=>new{x.id,x.coverToken,x.requires,x.loadAfter,x.loadBefore,x.conflicts}).ToArray())+"|"+string.Join("|",allowed.OrderBy(x=>x));if(budget.Incomplete)throw new Exception("模组来源未在有界读取预算内完整核实，暂不应用。");return Order(ValidatePreflightMods(mods),entries,warnings,allowed);}
  internal static SortResult SortForPreflight(Engine e,string[] mods,LaunchReadBudget budget=null){budget=budget??new LaunchReadBudget(16777216);var warnings=new List<string>();var catalog=SaveProfiles.PreflightEntries(e,mods,warnings,budget);return SortPreflight(e,mods,budget,catalog,warnings);}
  internal static SortResult SortPreflight(Engine e,string[] mods,LaunchReadBudget budget,SaveProfiles.PreflightCatalog catalog,List<string> warnings){var entries=catalog.Entries;var allowed=LoaderIds(e,mods);var known=catalog.KnownIds;if(mods!=null){var unknown=mods.Where(id=>id!=null&&!known.Contains(id)&&!allowed.Contains(id)).ToArray();if(unknown.Length>0){allowed.UnionWith(unknown);warnings.Add("部分启用模组来源未在已知目录中核实；未扫描未记录的 Steam 库，不能断言文件缺失。");}}if(budget.Incomplete)warnings.Add("部分扩展或元数据未在累计读取预算内核实。");return Order(mods,entries,warnings,allowed);}
  internal static SortResult SortSavedPreflight(Engine e,string[] mods,SaveProfiles.PreflightCatalog catalog,List<string> warnings){return Order(mods,catalog.Entries,warnings,LoaderIds(e,mods));}
  internal static SortResult Order(string[] input,List<SaveProfiles.Entry> entries,List<string> warnings,HashSet<string> allowedMissing){string[] ids;try{ids=Mods(input);}catch(Exception x){return new SortResult{mods=input??new string[0],warnings=Bound(warnings),errors=new[]{x.Message},violations=new string[0],changed=false};}var errors=new List<string>();var violations=new List<string>();var selected=new HashSet<string>(ids,StringComparer.Ordinal);Func<string,string> resolve=dep=>selected.Contains(dep)?dep:ids.FirstOrDefault(value=>value.TrimStart('\\')==dep&&Managed(new[]{value}).Length>0)??dep;var positions=ids.Select((id,index)=>new{id,index}).ToDictionary(p=>p.id,p=>p.index,StringComparer.Ordinal);var lookup=entries.GroupBy(m=>m.id,StringComparer.Ordinal).ToDictionary(g=>g.Key,g=>g.ToArray(),StringComparer.Ordinal);var edges=ids.ToDictionary(id=>id,id=>new HashSet<string>(StringComparer.Ordinal),StringComparer.Ordinal);var indegree=ids.ToDictionary(id=>id,id=>0,StringComparer.Ordinal);Action<string,string> edge=(before,after)=>{if(edges[before].Add(after)){indegree[after]++;if(positions[before]>=positions[after])violations.Add("加载顺序："+before+" → "+after+"（前者必须先加载）");}};foreach(string id in ids){SaveProfiles.Entry[] found;if(!lookup.TryGetValue(id,out found)&&!(Managed(new[]{id}).Length>0&&lookup.TryGetValue(id.TrimStart('\\'),out found))){if(!allowedMissing.Contains(id))errors.Add("模组未下载或本地目录缺失："+id);continue;}if(found.Length!=1){errors.Add("模组 ID 存在多个来源冲突："+id);continue;}var entry=found[0];foreach(string raw in entry.requires){string dep=resolve(raw);if(!SaveProfiles.Id(dep))errors.Add("无效依赖 ID："+id);else if(!selected.Contains(dep))errors.Add("缺少依赖："+id+" → "+dep);else edge(dep,id);}foreach(string raw in entry.loadAfter){string dep=resolve(raw);if(!SaveProfiles.Id(dep))errors.Add("无效 loadAfter ID："+id);else if(selected.Contains(dep))edge(dep,id);}foreach(string raw in entry.loadBefore){string dep=resolve(raw);if(!SaveProfiles.Id(dep))errors.Add("无效 loadBefore ID："+id);else if(selected.Contains(dep))edge(id,dep);}foreach(string raw in entry.conflicts){string conflict=resolve(raw);if(!SaveProfiles.Id(conflict))errors.Add("无效冲突 ID："+id);else if(selected.Contains(conflict))errors.Add("作者声明模组冲突："+id+" ↔ "+conflict);}}
   var output=new List<string>();var completed=new HashSet<string>(StringComparer.Ordinal);while(output.Count<ids.Length){string next=ids.FirstOrDefault(id=>!completed.Contains(id)&&indegree[id]==0);if(next==null)break;completed.Add(next);output.Add(next);foreach(string following in edges[next])indegree[following]--;}
   string[] blocked;string[][] cycles=CycleGroups(ids.Where(id=>!completed.Contains(id)).ToArray(),edges,positions,out blocked);foreach(var cycle in cycles)errors.Add("依赖或加载顺序存在循环："+string.Join("、",cycle.Take(40)));if(blocked.Length>0)warnings.Add("受循环阻塞（不是循环成员）："+string.Join("、",blocked.Take(40)));
   bool valid=errors.Count==0;string[] order=valid?output.ToArray():input;return new SortResult{mods=order,warnings=Bound(warnings),errors=Bound(errors),violations=Bound(violations),cycles=cycles,blockedByCycles=blocked,changed=valid&&!order.SequenceEqual(input)};}
  // Iterative SCC traversal avoids recursive stack growth for long mod lists.
  static string[][] CycleGroups(string[] remaining,Dictionary<string,HashSet<string>> edges,Dictionary<string,int> positions,out string[] blocked){
   var residual=new HashSet<string>(remaining,StringComparer.Ordinal);var visited=new HashSet<string>(StringComparer.Ordinal);var finished=new List<string>();
   foreach(string start in remaining){if(!visited.Add(start))continue;var nodes=new Stack<string>();var walks=new Stack<IEnumerator<string>>();nodes.Push(start);walks.Push(edges[start].GetEnumerator());while(walks.Count>0){var walk=walks.Peek();if(walk.MoveNext()){string next=walk.Current;if(residual.Contains(next)&&visited.Add(next)){nodes.Push(next);walks.Push(edges[next].GetEnumerator());}}else{walk.Dispose();walks.Pop();finished.Add(nodes.Pop());}}}
   var reverse=remaining.ToDictionary(id=>id,id=>new List<string>(),StringComparer.Ordinal);foreach(string before in remaining)foreach(string after in edges[before])if(residual.Contains(after))reverse[after].Add(before);
   visited.Clear();var groups=new List<string[]>();var members=new HashSet<string>(StringComparer.Ordinal);for(int i=finished.Count-1;i>=0;i--){string start=finished[i];if(!visited.Add(start))continue;var group=new List<string>();var pending=new Stack<string>();pending.Push(start);while(pending.Count>0){string id=pending.Pop();group.Add(id);foreach(string previous in reverse[id])if(visited.Add(previous))pending.Push(previous);}if(group.Count>1||edges[start].Contains(start)){var cycle=group.OrderBy(id=>positions[id]).ToArray();groups.Add(cycle);members.UnionWith(cycle);}}
   blocked=remaining.Where(id=>!members.Contains(id)).ToArray();return groups.OrderBy(group=>positions[group[0]]).ToArray();
  }
  static string[] Bound(IEnumerable<string> values){return values.Select(s=>s.Length<=512?s:s.Substring(0,512)).Distinct(StringComparer.Ordinal).Take(100).ToArray();}
 }
}
